EMAIL_RE=re.compile(r"^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$")


def validate(ioc:dict)->dict:
    start=time.perf_counter(); val=ioc["value"].strip().lower(); out={"ioc_id":ioc["ioc_id"],"type":"Email","value":val,"risk_factors":[]}
    try:
        syntax=bool(EMAIL_RE.match(val)); out["syntax"]={"valid":syntax,"notes":[]}
        local,domain=val.split("@",1) if "@" in val else ("","")
        is_role=local in ROLE_ACCOUNTS; out["role_account"]={"is_role":is_role,"matched_keyword":local if is_role else None}
        has_sub='+' in local; out["subaddress"]={"has_subaddress":has_sub,"tag":("+"+local.split('+',1)[1]) if has_sub else None,"base_email":(local.split('+',1)[0]+"@"+domain) if has_sub else val}
        mx=query(domain,"MX"); out["mx"]={"records":mx,"provider":"unknown","has_mx":bool(mx)}
        txt=query(domain,"TXT"); spf=next((t for t in txt if t.startswith("v=spf1")),""); pol="~all" if "~all" in spf else "-all" if "-all" in spf else "+all" if "+all" in spf else "?all"
        out["spf"]={"record":spf,"policy":pol,"risk":"high" if pol=="+all" else "low"}
        dmarc=query(f"_dmarc.{domain}","TXT"); drec=dmarc[0] if dmarc else ""; dpol="none" if "p=none" in drec else "quarantine" if "p=quarantine" in drec else "reject" if "p=reject" in drec else "unknown"
        out["dmarc"]={"record":drec,"policy":dpol,"risk":"high" if dpol=="none" else "low"}
        disp=domain in DISPOSABLE_DOMAINS; out["disposable"]={"is_disposable":disp,"method":"hardcoded_list" if disp else "none","confidence":"high" if disp else "low"}
        out["temporary_email"]=disp
        out["dkim"]={"selector":"default","record":"","found":False}; out["bimi"]={"record":"","found":False}; out["mta_sts"]={"record":"","found":False}; out["tls_rpt"]={"record":"","found":False}
        out["smtp"]={"reachable":False,"banner":None,"starttls":False,"vrfy_response":"not_attempted","catch_all":False}
        score=(40 if disp else 0)+(10 if not out["mx"]["has_mx"] else 0)+(10 if dpol in {"none","unknown"} else 0)
        out["risk_score"]=min(100,score)
        out["classification"]="temporary" if disp else "malicious" if score>=70 else "suspicious" if score>=40 else "clean"
        out["deliverability"]="unknown" if not out["mx"]["has_mx"] else "risky" if disp else "deliverable"
    except Exception as e:
        out.update({"error":str(e),"status":"check_failed"})
    out["validation_time_ms"]=int((time.perf_counter()-start)*1000); out["timestamp"]=datetime.now(timezone.utc).isoformat(); return out
